from protean import Domain, current_domain, handle, invariant
from protean.exceptions import ValidationError
from protean.fields import Identifier, String

domain = Domain(name="ordering")

ORDER_STATUSES = ["draft", "placed", "cancelled"]


@domain.aggregate
class Order:
    customer_name = String(required=True, max_length=100)
    status = String(max_length=20, choices=ORDER_STATUSES, default="draft")

    @classmethod
    def place(cls, order_id: str, customer_name: str) -> "Order":
        return cls(id=order_id, customer_name=customer_name, status="placed")

    @invariant.post
    def customer_name_must_not_be_blank(self):
        if self.customer_name is not None and not self.customer_name.strip():
            raise ValidationError(
                {"customer_name": ["Customer name cannot be blank"]}
            )


@domain.command(part_of="Order")
class PlaceOrder:
    order_id = Identifier(required=True)
    customer_name = String(required=True, max_length=100)


@domain.command_handler(part_of=Order)
class OrderCommandHandler:
    @handle(PlaceOrder)
    def place_order(self, command: PlaceOrder):
        order = Order.place(
            order_id=command.order_id,
            customer_name=command.customer_name,
        )
        current_domain.repository_for(Order).add(order)
        return order.id
